// Error Trigger gives us { execution: {...}, workflow: {...} } (or a trigger-level shape).
// Flatten it into one predictable record so every alert looks the same.
const e = $json.execution || {};
const w = $json.workflow || {};
const err = e.error || $json.error || {};
const nodeName = (err.node && err.node.name) || e.lastNodeExecuted || $json.node?.name || 'unknown node';
const message = String(err.message || err.description || 'no message').replace(/\s+/g, ' ').trim();
const fingerprint = [w.id || w.name || 'wf', nodeName, message.slice(0, 80)].join('|');
return [{ json: {
  workflow: w.name || 'unknown workflow',
  workflowId: w.id || null,
  executionId: e.id || null,
  executionUrl: e.url || null,
  mode: e.mode || $json.mode || null,
  node: nodeName,
  message,
  stack: (err.stack || '').split('\n').slice(0, 6).join('\n'),
  retryOf: e.retryOf || null,
  ts: new Date().toISOString(),
  fingerprint,
}}];

// One Slack message per distinct failure per window, not one per execution.
// A workflow firing every minute against a dead API sends 1 alert, then a count.
const WINDOW_MIN = 30;
const store = $getWorkflowStaticData('global');   // persists across production executions
store.seen = store.seen || {};
const now = Date.now();
const out = [];
for (const item of $input.all()) {
  const f = item.json.fingerprint;
  const rec = store.seen[f];
  const fresh = !rec || (now - rec.last) > WINDOW_MIN * 60 * 1000;
  if (fresh) {
    store.seen[f] = { first: now, last: now, count: 1 };
  } else {
    rec.last = now; rec.count += 1;
  }
  out.push({ json: { ...item.json, isNew: fresh, occurrences: store.seen[f].count, windowMin: WINDOW_MIN } });
}
// housekeeping: forget fingerprints older than a day so static data stays small
for (const [k, v] of Object.entries(store.seen)) if (now - v.last > 24 * 3600 * 1000) delete store.seen[k];
return out;

